class TrazmoHeader extends HTMLElement{connectedCallback(){fetch("./templates/header.html").then(e=>e.text()).then(e=>{this.innerHTML=e})}}class TrazmoFooter extends HTMLElement{connectedCallback(){fetch("./templates/footer.html").then(e=>e.text()).then(e=>{this.innerHTML=e})}}export function registerCustomElements(){customElements.define("trazmo-header",TrazmoHeader),customElements.define("trazmo-footer",TrazmoFooter)}